foreach (['en', 'fr', 'es', 'it', 'zh'] as $locale) {
    $path = $root . "/resources/lang/$locale.json";
    $json = json_decode(file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);

    foreach ($baseKeys as $key) {
        $json[$key] = $translations[$locale][$key] ?? $key;
    }
    foreach ($extraTranslations[$locale] ?? [] as $key => $value) {
        $json[$key] = $value;
    }

    ksort($json, SORT_STRING);
    file_put_contents(
        $path,
        json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . PHP_EOL
    );
}

echo "FlexiCare translations updated.\n";
